/**
 * Format multirange min/max counters with thousand separators.
 *
 * Target: Odoo website_sale price range filter counters generated by multirange.
 *
 * Notes:
 * - We format with en-US grouping to match "100,000" expectation.
 * - If a currency symbol is present, we re-apply it using the dataset hints.
 */
(function () {
    function parseNumberFromText(text) {
        if (!text) return null;
        const cleaned = String(text)
            .trim()
            // keep digits, dot, comma, minus
            .replace(/[^0-9.,-]/g, '');
        if (!cleaned) return null;
        // remove grouping commas and parse
        const normalized = cleaned.replace(/,/g, '');
        const value = Number.parseFloat(normalized);
        return Number.isFinite(value) ? value : null;
    }

    function formatIntWithCommas(value) {
        const rounded = Math.round(value);
        return rounded.toLocaleString('en-US', { maximumFractionDigits: 0 });
    }

    function decorateWithCurrency(formatted, inputEl) {
        if (!inputEl) return formatted;
        const currency = inputEl.dataset.currency;
        const position = inputEl.dataset.currencyPosition;
        if (!currency) return formatted;
        if (position === 'before') {
            return `${currency} ${formatted}`;
        }
        return `${formatted} ${currency}`;
    }

    function formatCounterEl(counterEl, inputEl) {
        const value = parseNumberFromText(counterEl.textContent);
        if (value === null) return;
        const formatted = formatIntWithCommas(value);
        counterEl.textContent = decorateWithCurrency(formatted, inputEl);
    }

    function formatContainer(container) {
        const inputEl = container.querySelector('input.range-with-input');
        const minEl = container.querySelector('.multirange-wrapper .multirange-min');
        const maxEl = container.querySelector('.multirange-wrapper .multirange-max');
        if (minEl) formatCounterEl(minEl, inputEl);
        if (maxEl) formatCounterEl(maxEl, inputEl);
    }

    function setup(containerSelector) {
        const container = document.querySelector(containerSelector);
        if (!container) return;

        // Initial formatting (after multirange builds DOM)
        window.setTimeout(() => formatContainer(container), 0);

        // Reformat on input changes
        container.addEventListener('input', () => formatContainer(container), { capture: true });
        container.addEventListener('change', () => formatContainer(container), { capture: true });

        // Reformat if multirange updates the counters
        const observer = new MutationObserver(() => formatContainer(container));
        observer.observe(container, { subtree: true, childList: true, characterData: true });
    }

    document.addEventListener('DOMContentLoaded', function () {
        setup('#o_wsale_price_range_option');
        setup('#smileliving_area_range_option');
    });
})();
